package org.brightstats.stats;

import java.util.*;
import org.apache.commons.math3.linear.*;
import org.apache.commons.math3.distribution.NormalDistribution;

/** Continuous two-level random-intercept RAM model, exact cluster marginal ML. */
public final class TwoLevelSem {
    private TwoLevelSem(){}
    public record Specification(SemModel.Model within,SemModel.Model between){public Specification{
        Objects.requireNonNull(within);Objects.requireNonNull(between);List<String> a=Arrays.stream(within.observed()).mapToObj(i->within.variables().get(i)).toList(),b=Arrays.stream(between.observed()).mapToObj(i->between.variables().get(i)).toList();if(!a.equals(b)||a.size()>16||within.variables().size()>64||between.variables().size()>64||within.parameters().size()+between.parameters().size()>120)throw new IllegalArgumentException("Two-level observed names/order must match; at most 16 observed variables, 64 variables per level and 120 total free parameters.");if(Arrays.stream(within.intercepts()).anyMatch(x->x!=0)||within.parameters().stream().flatMap(p->p.locations().stream()).anyMatch(l->l.kind()==SemModel.Kind.INTERCEPT))throw new IllegalArgumentException("Within-level intercepts must be fixed at zero; all means belong to the between level.");}}
    public record Term(String level,String parameter,double estimate,double standardError,double clusterSandwichStandardError,double statistic,double pValue,double lower,double upper){}
    public record Fit(Specification specification,FimlSem.Options options,int observations,int clusters,List<Integer> clusterSizes,int iterations,boolean converged,boolean locallyIdentified,boolean boundary,double logLikelihood,double aic,double bicByClusters,double[] estimates,double[][] parameterCovariance,double[][] clusterSandwichCovariance,List<Term> terms,double[][] withinCovariance,double[][] betweenCovariance,double[] means,double[] intraclassCorrelations,List<String> warnings){
        public Fit{clusterSizes=List.copyOf(clusterSizes);estimates=estimates.clone();parameterCovariance=Matrices.copy(parameterCovariance);clusterSandwichCovariance=Matrices.copy(clusterSandwichCovariance);terms=List.copyOf(terms);withinCovariance=Matrices.copy(withinCovariance);betweenCovariance=Matrices.copy(betweenCovariance);means=means.clone();intraclassCorrelations=intraclassCorrelations.clone();warnings=List.copyOf(warnings);}
        @Override public double[] estimates(){return estimates.clone();}@Override public double[][] parameterCovariance(){return Matrices.copy(parameterCovariance);}@Override public double[][] clusterSandwichCovariance(){return Matrices.copy(clusterSandwichCovariance);}@Override public double[][] withinCovariance(){return Matrices.copy(withinCovariance);}@Override public double[][] betweenCovariance(){return Matrices.copy(betweenCovariance);}@Override public double[] means(){return means.clone();}@Override public double[] intraclassCorrelations(){return intraclassCorrelations.clone();}
    }
    record Group(int size,RealVector mean,RealMatrix withinSS){}
    static final class Work {
        final Specification specification;final List<Group> groups;final double[] scales;final int n,p,qw,q;final double jacobian;
        Work(double[][] data,List<String> ids,Specification specification){
            this.specification=specification;p=Matrices.width(data,20);n=data.length;qw=specification.within().parameters().size();q=qw+specification.between().parameters().size();if(n>20000||p!=specification.within().observed().length)throw new IllegalArgumentException("Two-level data must be complete, finite and follow the observed model order; at most 20,000 rows.");var indices=ClusterSem.groups(data,ids);if(indices.size()<5||indices.values().stream().noneMatch(rows->rows.size()>1))throw new IllegalArgumentException("Two-level ML requires at least five clusters and some repeated observations per cluster.");double[] average=new double[p],ss=new double[p];for(int i=0;i<n;i++)for(int j=0;j<p;j++){if(!Double.isFinite(data[i][j]))throw new IllegalArgumentException("Two-level ML currently requires explicitly selected complete continuous data.");double delta=data[i][j]-average[j];average[j]+=delta/(i+1);ss[j]+=delta*(data[i][j]-average[j]);}scales=new double[p];double log=0;for(int j=0;j<p;j++){scales[j]=Math.sqrt(ss[j]/n);if(!(scales[j]>0)||!Double.isFinite(scales[j]))throw new IllegalArgumentException("Two-level variables need positive finite variance.");log+=Math.log(scales[j]);}jacobian=log;List<Group> built=new ArrayList<>();for(var rows:indices.values()){double[] mean=new double[p];double[][] centeredSS=new double[p][p];int count=0;for(int row:rows){count++;double[] delta=new double[p];for(int j=0;j<p;j++){double value=data[row][j]/scales[j];delta[j]=value-mean[j];mean[j]+=delta[j]/count;}for(int i=0;i<p;i++)for(int j=0;j<p;j++)centeredSS[i][j]+=delta[i]*(data[row][j]/scales[j]-mean[j]);}built.add(new Group(count,new ArrayRealVector(mean),new Array2DRowRealMatrix(centeredSS)));}groups=List.copyOf(built);
        }
        RealMatrix normalize(RealMatrix covariance){double[][] out=covariance.getData();for(int i=0;i<p;i++)for(int j=0;j<p;j++)out[i][j]=out[i][j]/scales[i]/scales[j];return new Array2DRowRealMatrix(out);}
        RealVector normalize(RealVector vector){double[] out=vector.toArray();for(int j=0;j<p;j++)out[j]/=scales[j];return new ArrayRealVector(out);}
        Bfgs.Evaluation evaluate(double[] theta){return evaluate(theta,null);}
        Bfgs.Evaluation evaluate(double[] theta,double[][] unitScores){
            var within=RamMoments.state(specification.within(),Arrays.copyOfRange(theta,0,qw));var between=RamMoments.state(specification.between(),Arrays.copyOfRange(theta,qw,q));double[] gradient=new double[q];if(within==null||between==null)return new Bfgs.Evaluation(Double.POSITIVE_INFINITY,gradient);RealMatrix w=normalize(within.covariance()),b=normalize(between.covariance());RealVector mu=normalize(between.mean());double value=0;
            try{var cw=new CholeskyDecomposition(w,1e-9,1e-12);RealMatrix wi=cw.getSolver().getInverse();double logW=SemObservedLikelihood.logDet(cw);int unit=0;
                for(var group:groups){Matrices.interrupted();int ng=group.size();RealMatrix r=w.add(b.scalarMultiply(ng));var cr=new CholeskyDecomposition(r,1e-9,1e-12);RealMatrix ri=cr.getSolver().getInverse();RealVector difference=group.mean().subtract(mu),weighted=ri.operate(difference);value+=.5*(ng*p*Math.log(2*Math.PI)+(ng-1)*logW+SemObservedLikelihood.logDet(cr)+wi.multiply(group.withinSS()).getTrace()+ng*difference.dotProduct(weighted))+ng*jacobian;RealMatrix shared=ri.subtract(weighted.outerProduct(weighted).scalarMultiply(ng)),weightW=wi.scalarMultiply(ng-1).subtract(wi.multiply(group.withinSS()).multiply(wi)).add(shared),weightB=shared.scalarMultiply(ng);
                    for(int j=0;j<q;j++){double derivative=j<qw?.5*weightW.multiply(normalize(within.covarianceDerivatives().get(j))).getTrace():.5*weightB.multiply(normalize(between.covarianceDerivatives().get(j-qw))).getTrace()-ng*weighted.dotProduct(normalize(between.meanDerivatives().get(j-qw)));gradient[j]+=derivative;if(unitScores!=null)unitScores[unit][j]=derivative;}unit++;
                }
            }catch(NonPositiveDefiniteMatrixException|NonSymmetricMatrixException invalid){return new Bfgs.Evaluation(Double.POSITIVE_INFINITY,new double[q]);}for(int j=0;j<q;j++)gradient[j]/=n;return new Bfgs.Evaluation(value/n,gradient);
        }
    }
    public static Fit fit(double[][] data,List<String> ids,Specification specification,FimlSem.Options options){
        Work work=new Work(data,ids,specification);double[] initial=join(RamMoments.initial(specification.within()),RamMoments.initial(specification.between())),lower=join(RamMoments.lower(specification.within()),RamMoments.lower(specification.between())),upper=join(RamMoments.upper(specification.within()),RamMoments.upper(specification.between()));var optimum=Bfgs.minimize(work::evaluate,initial,lower,upper,options.maxIterations(),options.gradientTolerance(),options.functionTolerance());double[] theta=optimum.point();List<SemModel.Parameter> parameters=new ArrayList<>(specification.within().parameters());parameters.addAll(specification.between().parameters());boolean boundary=false;for(int j=0;j<theta.length;j++)if(Double.isFinite(lower[j])&&theta[j]-lower[j]<1e-7||Double.isFinite(upper[j])&&upper[j]-theta[j]<1e-7||parameters.get(j).locations().stream().anyMatch(l->l.kind()==SemModel.Kind.COVARIANCE&&l.row()==l.column())&&theta[j]<1e-7)boundary=true;double[] scales=parameters.stream().mapToDouble(SemModel.Parameter::scale).toArray();double[][] scores=new double[work.groups.size()][work.q];work.evaluate(theta,scores);var info=LikelihoodInformation.calculate(work::evaluate,theta,scales,work.n,optimum.converged()&&!boundary,scores);double[] estimates=new double[theta.length];List<Term> terms=new ArrayList<>();double critical=new NormalDistribution().inverseCumulativeProbability((1+options.confidence())/2);for(int j=0;j<theta.length;j++){var parameter=parameters.get(j);double estimate=estimates[j]=theta[j]*scales[j],se=Math.sqrt(info.model()[j][j]),robust=Math.sqrt(info.sandwich()[j][j]);boolean testable=parameter.locations().stream().noneMatch(l->l.kind()==SemModel.Kind.COVARIANCE);double z=testable?Inference.ratio(estimate,se):Double.NaN;terms.add(new Term(j<work.qw?"Within":"Between",parameter.name(),estimate,se,robust,z,Inference.normalTwoSided(z),estimate-critical*se,estimate+critical*se));}var within=RamMoments.state(specification.within(),Arrays.copyOfRange(theta,0,work.qw));var between=RamMoments.state(specification.between(),Arrays.copyOfRange(theta,work.qw,theta.length));if(within==null||between==null)throw new IllegalArgumentException("Inadmissible final two-level state.");double[] icc=new double[work.p];for(int j=0;j<icc.length;j++)icc[j]=between.covariance().getEntry(j,j)/(within.covariance().getEntry(j,j)+between.covariance().getEntry(j,j));double ll=-optimum.evaluation().value()*work.n;List<String> warnings=new ArrayList<>();warnings.add("Exact continuous Gaussian two-level random-intercept marginal likelihood with separate within/between RAM covariance structures. Cluster IDs are sampling units, not measurement hierarchy levels. Complete selected data are required; missing values are not silently replaced or removed.");warnings.add("Between-level means are free/fixed according to the model; within means are fixed at zero. Random slopes, ordinal responses, cross-level interactions and cross-level equality constraints are not implemented in this estimator. BIC uses the number of independent clusters explicitly.");warnings.add("Cluster sandwich covariance is CR0 without a finite-cluster correction. Ordinary model Wald intervals and cluster sandwich SE are distinct; no fabricated global fit indices or variance-component P values are supplied.");if(work.groups.size()<30)warnings.add("Fewer than 30 clusters; between-level and sandwich inference may be unstable.");if(!optimum.converged())warnings.add("Optimizer did not converge; inference unavailable.");if(!info.identified())warnings.add("Observed information is singular, indefinite or weak; inference unavailable.");if(boundary)warnings.add("A parameter or free variance is at a boundary; ordinary Wald inference unavailable.");return new Fit(specification,options,work.n,work.groups.size(),work.groups.stream().map(Group::size).toList(),optimum.iterations(),optimum.converged(),info.identified(),boundary,ll,-2*ll+2*work.q,-2*ll+Math.log(work.groups.size())*work.q,estimates,info.model(),info.sandwich(),terms,within.covariance().getData(),between.covariance().getData(),between.mean().toArray(),icc,warnings);
    }
    private static double[] join(double[] a,double[] b){double[] out=Arrays.copyOf(a,a.length+b.length);System.arraycopy(b,0,out,a.length,b.length);return out;}
}
